{"srp": false, "orgaoEntidade": {"cnpj": "11633713000109", "razaoSocial": "DEPARTAMENTO ESTADUAL DE TRANSITO DO ESTADO DO AMAPA", "poderId": "E", "esferaId": "E"}, "anoCompra": 2025, "sequencialCompra": 20, "dataInclusao": "2025-09-23T12:25:00", "dataPublicacaoPncp": "2025-09-23T12:25:00", "dataAtualizacao": "2025-09-23T12:25:00", "numeroCompra": "9", "unidadeOrgao": {"ufNome": "Amapá", "codigoUnidade": "63", "nomeUnidade": "DEPARTAMENTO ESTADUAL DE TRÂNSITO ", "ufSigla": "AP", "municipioNome": "Amapá", "codigoIbge": "1600105"}, "amparoLegal": {"descricao": "Dispensa de Licitação: para contratação que envolva valores inferiores a R$ 50.000,00 (cinquenta mil reais), no caso de outros serviços e compras", "nome": "Lei 14.133/2021, Art. 75, II", "codigo": 19}, "dataAberturaProposta": null, "dataEncerramentoProposta": null, "informacaoComplementar": "Com a contratação de empresa especializada para ministrar curso de capacitação técnica voltado à utilização do software Revit espera-se:
Capacitar a equipe para utilizar o REVIT de forma eficiente, explorando suas ferramentas de modelagem, documentação e coordenação de projetos;
Elevar o padrão técnico dos projetos desenvolvidos, com maior precisão, detalhamento e padronização;
Preparar os participantes para trabalhar dentro da lógica BIM, promovendo integração entre as diversas disciplinas do projeto (arquitetura, estrutura, instalações);
Diminuir erros comuns de projeto e tempo gasto em alterações manuais, com ganho de eficiência na elaboração e revisão dos projetos;
Habilitar os profissionais a trabalhar em equipes multidisciplinares, utilizando recursos de colaboração e compartilhamento de modelos;
Desenvolver os servidores com conhecimento suficiente para apoiar e treinar outros membros da equipe.", "processo": "00016/DETRAN/2025", "objetoCompra": "CONTRATAÇÃO DE EMPRESA ESPECIALIZADA PARA MINISTRAR CURSO DE CAPACITAÇÃO TÉCNICA VOLTADA À ULTILIZAÇÃO DE SOFTWARE REVIT, COM FOCO NA METODOLOGIA BIM (BUILDING INFORMATION MODELING), PARA OS SERVIDORES DO SETOR DA DIRETORIA TÉCNICA (ENGENHARIA) DO DETRAN/AP.", "linkSistemaOrigem": null, "justificativaPresencial": null, "unidadeSubRogada": null, "orgaoSubRogado": null, "valorTotalHomologado": 11000.0, "modalidadeId": 8, "numeroControlePNCP": "11633713000109-1-000020/2025", "modoDisputaId": 5, "linkProcessoEletronico": null, "emendaParlamentar": null, "dataAtualizacaoGlobal": "2025-10-13T12:00:00", "valorTotalEstimado": 14226.7, "modalidadeNome": "Dispensa", "modoDisputaNome": "Não se aplica", "tipoInstrumentoConvocatorioCodigo": 3, "tipoInstrumentoConvocatorioNome": "Ato que autoriza a Contratação Direta", "fontesOrcamentarias": [], "situacaoCompraId": 1, "situacaoCompraNome": "Divulgada no PNCP", "usuarioNome": "AZ INFORMATICA LTDA"}

{"amparoLegal": {"codigo": 19, "descricao": "Dispensa de Licitação: para contratação que envolva valores inferiores a R$ 50.000,00 (cinquenta mil reais), no caso de outros serviços e compras", "nome": "Lei 14.133/2021, Art. 75, II"}, "unidadeSubRogada": null, "orgaoSubRogado": null, "valorTotalHomologado": 55000.0, "dataAberturaProposta": null, "dataEncerramentoProposta": null, "informacaoComplementar": "A presente contratação se justifica pela grande movimentação do setor turístico do município de Macapá, facilitando a forma como as informações turísticas são disponibilizadas e acessadas. Essa iniciativa visa posicionar Macapá como um destino turístico de referência na Amazônia, para aprimorar a experiência dos visitantes e fortalecer a identidade turística da capital.
A contratação está alinhada ao planejamento estratégico municipal, especialmente às políticas de fomento ao turismo, contribuindo para:
-Valorização da cultura, história e gastronomia local;
-Fortalecimento da imagem do município como destino turístico;
- Incremento do fluxo turístico e da economia local.
", "processo": "0756.01.059/2025", "objetoCompra": "Dispensa de licitação para confecção e impressão de 50.000 (cinquenta mil) exemplares do Guia Turístico de Macapá, no formato A2(42x59,4 cm), dobrado para formato prático, para atender as ações de promoção turística do município, atendendo assim a demanda do instituto Municipal de Turismo - MACAPATUR.  ", "linkSistemaOrigem": null, "justificativaPresencial": null, "srp": false, "orgaoEntidade": {"cnpj": "15714722000185", "razaoSocial": "INSTITUTO MUNICIPAL DE TURISMO", "poderId": "E", "esferaId": "M"}, "anoCompra": 2025, "sequencialCompra": 3, "dataInclusao": "2025-10-17T13:21:35", "dataPublicacaoPncp": "2025-10-17T13:21:35", "dataAtualizacao": "2025-10-17T13:21:35", "numeroCompra": "5", "unidadeOrgao": {"ufNome": "Amapá", "municipioNome": "Macapá", "ufSigla": "AP", "codigoUnidade": "933007", "nomeUnidade": "MAP-INSTITUTO MUNICIPAL DE TURISMO", "codigoIbge": "1600303"}, "dataAtualizacaoGlobal": "2025-10-17T13:24:35", "emendaParlamentar": null, "numeroControlePNCP": "15714722000185-1-000003/2025", "linkProcessoEletronico": null, "modoDisputaId": 5, "modalidadeId": 8, "valorTotalEstimado": 55000.0, "modalidadeNome": "Dispensa", "modoDisputaNome": "Não se aplica", "tipoInstrumentoConvocatorioCodigo": 3, "tipoInstrumentoConvocatorioNome": "Ato que autoriza a Contratação Direta", "fontesOrcamentarias": [], "situacaoCompraId": 1, "situacaoCompraNome": "Divulgada no PNCP", "usuarioNome": "Compras.gov.br"}

